"""Clase autónoma ejecutiva. Fuente única de slides y tiempos,180 minutos."""
import sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]/'editorial'))
from guion import slide,p,step,table,flow,code,proof,lablink,source
SAMPLE='Muestra real de all_data.csv · 4500 filas · tres ventanas · inspección 2026-11-09'
BQ=source('Google Cloud · consultas BigQuery','https://docs.cloud.google.com/bigquery/docs/running-queries')
COST=source('Google Cloud · estimación y control','https://docs.cloud.google.com/bigquery/docs/best-practices-costs')
ARCH=source('Google Cloud · lakehouse','https://cloud.google.com/discover/what-is-a-data-lakehouse')
SLIDES=[]
def add(title,body,note,layout='plain',phase='BigQuery · 0–30 min',src=SAMPLE):SLIDES.append(slide(title,body,note,layout,phase,src))
add('El precio menor necesita contexto.','<div><p class="overline">BigQuery · arquitectura · Medallion</p><h1>El precio menor<br>necesita contexto.</h1><p class="lede">Una clase para decidir<br>qué pedirle al sistema de datos.</p></div><div class="stack"><p class="large signal">15.10</p><p>frente a 15.50 MXN</p><p class="caption">Mismo refresco · 2 L · Tlalpan<br>19 de marzo de 2014 · dos tiendas observadas</p></div>','0–5 min. Preguntar si recomendarían comprar hoy con esta pantalla. [pausa 3 s] La diferencia es real en la muestra; el salto a hoy no está sustentado. El ejecutivo debe identificar la población y la fecha antes de aprobar una decisión.','cover dark')
add('La muestra enseña el flujo; no describe todo el archivo.','<div class="two"><div><p class="large">4500</p><p>filas seleccionadas</p></div><div><p class="large">20.7 GB</p><p>archivo remoto · bytes decimales</p></div></div>'+step(1,p('Tres ventanas contiguas. Sin muestreo aleatorio.','callout')),'5–10 min. Se leyeron 6 MiB en total: inicio, mitad y final; se seleccionaron 1500 registros completos por ventana. Las fechas vistas incluyen 2011, 2014 y 2015. No son el mínimo y máximo global. El archivo pesa 20663702126 bytes según Content-Range; tamaño distinto de bytes facturados por BigQuery.','comparison')
add('BigQuery separa los datos del trabajo de consultarlos.',flow([('Almacenamiento','Tablas y columnas'),('Consulta SQL','Trabajo distribuido'),('Resultado','Filas para decidir')]),'10–15 min. BigQuery es una plataforma analítica administrada: el usuario no dimensiona una VM por consulta. El servicio ejecuta trabajos, coordina cómputo y conserva resultados. El almacenamiento y la ejecución tienen costos y responsabilidades diferentes. No usarlo como sustituto automático de una base transaccional de caja.','path',src=BQ)
add('Una consulta ocurre dentro de un proyecto.',flow([('Proyecto','Permisos y facturación'),('Dataset','Ubicación y organización'),('Tabla','Esquema y datos')])+step(2,p('Cada ejecución genera un job que puedes inspeccionar.','callout')),'15–20 min. Dibujar la ruta proyecto.dataset.tabla. El proyecto de ejecución paga el trabajo según configuración; el propietario del dato administra su almacenamiento. En consola el selector de proyecto y la región importan. Abrir un trabajo permite revisar bytes, tiempos y errores.','path',src=BQ)
add('SQL expresa la pregunta; el motor decide cómo ejecutarla.',code("SELECT establecimiento, MIN(precio_mxn) AS precio_mxn\nFROM emergente_silver.precios\nWHERE fecha = DATE '2014-03-19'\n  AND producto = 'REFRESCO'\nGROUP BY establecimiento;"),'20–25 min. Lectura guiada: columnas, tabla, filas elegidas y agrupación. Este fragmento es para explicar SQL, no una comparación comercial válida: faltan marca, presentación y geografía. Pedir detectar esos filtros; el archivo05 contiene la versión completa. No se requiere que memoricen sintaxis.','query',src=BQ)
add('LIMIT cambia la salida; el filtro puede evitar lectura.','<div class="scan-model" data-scan-model><div class="actions"><button data-scan-mode="all" aria-pressed="true">Sin filtro</button><button data-scan-mode="limit" aria-pressed="false">LIMIT 10</button><button data-scan-mode="month" aria-pressed="false">Un mes</button></div><div class="month-blocks">'+''.join(f'<div>{i:02}</div>' for i in range(1,13))+'</div><p data-scan-result role="status">Modelo didáctico: se leen las doce particiones.</p><p class="caption">Representación de un año. No son bytes ni tiempos medidos.</p></div>','25–30 min. Activar LIMIT: todas las particiones siguen relevantes. Activar un mes: el predicado sobre la columna de partición permite poda. En el laboratorio mediremos bytes reales; clustering puede reducir bloques y la estimación previa puede ser una cota superior. Una tabla pequeña puede no mostrar ahorro facturable.','scan',src=COST)
add('La arquitectura depende del uso y del equipo.','<div data-architecture class="architecture-choice"><div class="actions"><button data-arch="warehouse" aria-pressed="true">Warehouse</button><button data-arch="lake" aria-pressed="false">Lake + warehouse</button><button data-arch="lakehouse" aria-pressed="false">Lakehouse</button></div><h2 data-arch-title>Fuentes → BigQuery → BI</h2><p data-arch-use>Datos estructurados y consumo analítico en SQL.</p><p class="callout" data-arch-cost>Operación acotada; requiere contratos claros de carga y métricas.</p></div>','30–37 min. Cambiar entre opciones. Warehouse: tablas analíticas gestionadas. Lake+warehouse: archivos originales y tablas curadas; copias y sincronización deben gobernarse. Lakehouse: formatos de tabla abiertos, catálogo y motores compatibles sobre objetos; más decisiones operativas. No afirmar que cualquier bucket más BigQuery ya equivale a un lakehouse abierto.','architecture-choice','Arquitecturas · 30–50 min',ARCH)
add('Para este taller basta conservar el original y servir tablas.',flow([('GCS','Archivo y manifiesto'),('BigQuery','Transformación y controles'),('Consumo','Consulta o dashboard')]),'37–43 min. Propuesta para all_data completo: docente prepara el archivo en GCS, carga una vez en BigQuery y sirve tablas pequeñas. El alumno usa muestra descargable para evitar traslado de 20.7 GB durante clase. Variante warehouse directo viable para el laboratorio; no se requiere contratar BigLake, Spark ni streaming.','path','Arquitecturas · 30–50 min',ARCH)
add('La frecuencia del dato define cómo llega.',table(['Necesidad','Patrón','Costo operativo'],[['Archivo periódico','Batch por lotes','Controlar versión y repetición'],['Cambios de una base','CDC','Conectores y orden de cambios'],['Eventos en segundos','Streaming','Latencia, duplicados y operación']]),'43–50 min. QQP en archivos periódicos permite batch. Más servicios no crean datos más frescos que la fuente. CDC y streaming son alternativas para otras fuentes; no forman parte del despliegue del taller. Pedir qué SLA justificaría abandonar el lote.','choices','Arquitecturas · 30–50 min')
add('Medallion organiza responsabilidades sobre el dato.',flow([('Bronze','Qué recibimos'),('Silver','Qué podemos comparar'),('Gold','Qué necesita la decisión')]),'50–55 min. Medallion es un patrón de capas de calidad, compatible con varias arquitecturas físicas. No es un servicio de GCP ni exige tres tecnologías diferentes. Aquí son datasets separados; otras organizaciones pueden resolverlo con esquemas, tablas o productos.','path','Medallion · 50–70 min')
add('Bronze conserva lo que llegó, incluso sus problemas.','<div class="receipt"><p class="mono">municipio = "TLALPAN       "</p><p class="mono">fechaRegistro = "2014-03-19 00:00:00.000"</p><p class="caption">Más lote, fuente y fecha de ingesta.</p></div>','55–59 min. Mantener 15 columnas como STRING en entrada evita inferencias incorrectas de tipos. Bronze conserva los valores y duplicados, con un hash técnico de fila y un lote. La copia CSV original conserva bytes y cabecera; la tabla no es una copia binaria del archivo.','raw','Medallion · 50–70 min')
add('Silver hace explícitas las reglas de confianza.','<div class="two"><div class="stack"><p class="caption">ANTES</p><p class="mono">"TLALPAN       "</p><p class="mono">"15.1"</p></div><div class="stack"><p class="caption">DESPUÉS</p><p class="mono signal">TLALPAN</p><p class="mono">NUMERIC · 15.1</p></div></div>'+step(1,p('Rechaza con motivo. Reconcilia lo que aceptas.','callout')),'59–63 min. La muestra contiene 3000 municipios con espacios finales y cero precios no positivos. No inventar errores para prometer rechazos. SAFE_CAST devuelve NULL ante un dato inválido; definir reglas de negocio después del parseo. Estado histórico se conserva: no convertir Distrito Federal a CDMX sin tabla de equivalencias aprobada.','cleaning','Medallion · 50–70 min')
add('Gold conserva el grano de la comparación.',p('Producto + marca + presentación','callout')+p('Misma fecha y municipio. Una fila por tienda.')+step(1,p('Dos precios distintos en la misma tienda: conflicto visible.')),'63–67 min. No sumar precios como ventas. Gold produce precio por producto/tienda/día y luego comparación por producto/día/municipio. Si hay más de un precio en el grupo, se marca conflicto y se excluye ese valor del ranking. S/M significa marca no especificada: no demuestra equivalencia entre marcas desconocidas.','grain','Medallion · 50–70 min')
add('Cada capa necesita un dueño y una regla de acceso.',table(['Capa','Responsabilidad'],[['Bronze','Procedencia, versión y conservación'],['Silver','Reglas, rechazos y reconciliación'],['Gold','Definición de KPI y audiencia']]),'67–70 min. El ejecutivo exige responsable de actualización, acceso y retención. Los datasets separados permiten asignar permisos; el taller no configura políticas de producción automáticamente. La trazabilidad acompaña cada entrega.','governance','Medallion · 50–70 min')
add('Pausa. Abriremos el dato que acabamos de discutir.','<p class="huge">10 min</p><p>Proyecto autorizado, muestra y guía.</p>','70–80 min. Confirmar acceso al proyecto docente, facturación y permisos antes de continuar. No crear cuentas o recursos de pago a ciegas durante clase. Si falta acceso, seguir el perfil y consultas como revisión, dejando ejecución pendiente.','statement dark','Pausa · 70–80 min')
labs=[
('Carga la muestra con un esquema explícito.',flow([('Preparar','00_preparar.sql'),('Cargar CSV','4500 filas ·15 columnas'),('Entrada','Todos los campos STRING')]),'COUNT(*) de entrada =4500, sin filas rechazadas por el cargador.','80–95 min. Paso1: abrir BigQuery Studio, ejecutar 00 y cargar CSV local en emergente_bronze.entrada. Cabecera1, comillas dobles, UTF8, sin autodetección. Esquema descargable. Seguir guía si el asistente cambia de nombre.'),
('Registra un lote que puedas reconocer mañana.',code("DECLARE lote STRING DEFAULT 'all_data_muestra_v1';\n-- Ejecuta 01_ingestar_bronze.sql completo.\nSELECT lote_id, COUNT(*) AS filas\nFROM emergente_bronze.observaciones\nGROUP BY lote_id;"),'4500 filas en el primer lote. Repetir el mismo ID debe detener la carga.','95–105 min. Paso2: ejecutar 01 completo. La protección es serial por ID de lote; no es un sistema transaccional multiusuario. Mantener proyecto aislado por equipo. Para el archivo completo cambiar ID y fuente, no el contrato de campos.'),
('Perfila antes de aceptar una regla.',p('3000 / 4500','large')+p('municipios con espacios al final.')+step(1,p('Este hallazgo pertenece a la muestra.','callout')),'Coinciden conteos y fechas con perfil-muestra.json.','105–115 min. Paso3:02_perfil.sql. Revisar mínimo/máximo de la muestra, duplicados exactos y conversiones. La falta de errores en una muestra no garantiza calidad global. Identificar el par deREFRESCO/SPRITE con el mismo periodo y presentación.'),
('Tipa, clasifica y conserva los rechazos.',flow([('Raw','Valores originales'),('Reglas','Parseo y contrato'),('Silver','Aceptadas + rechazadas')]),'Entrada = duplicadas exactas + aceptadas + rechazadas.','115–130 min. Paso4: ejecutar 03 completo. Reconstruye Silver desde Bronze y crea copia plana parabenchmark. Filtra fechas al consultar la particionada. Los hashes derivados no son IDs oficiales ni resuelven cambios de dirección. No confundir limpieza textual con identidad comercial.'),
('Publica una comparación con sus condiciones.',table(['Muestra ·19/03/2014','Precio MXN'],[['Comercial Mexicana ·Coapa','15.50'],['Mega Comercial Mexicana ·Coapa','15.10']]),'Dos tiendas comparables; diferencia observada 0.40 MXN.','130–140 min. Paso5:04_gold.sql. Abrir detalle y agregado. Explicar que no existe cobertura de todas las tiendas ni inventario. Se construyeGold pequeña para consultas repetidas, pagando la transformación y el almacenamiento correspondientes.'),
('Optimiza la misma pregunta, no una respuesta distinta.',flow([('A ·plana','Línea base'),('B ·particionada','Mismo SQL'),('C ·Gold','Agregado mantenido')]),'Resultados equivalentes antes de comparar bytes y tiempo.','140–150 min. Paso6: ejecutar cada SELECT de 05 por separado, caché desactivada. Registrarjob ID, bytes estimados/procesados/facturados y tiempo. A/B comparan organización física. C solo es equivalente si no hay conflictos. La muestra puede quedar bajo mínimos de facturación; no prometer porcentajes.'),
('Conserva la prueba y retira la copia temporal.',p('Resultado + job + bytes + límite','callout')+p('Guarda tu registro antes del cierre.'),'06_validar.sql sin diferencias A/B.07 elimina solo la tabla plana de benchmark.','150–160 min. Paso7: entregar controles y registro-optimizacion.csv. Revisar expiraciones. Cerrar pestaña no elimina almacenamiento; no borrar datasets ajenos niBronze por comodidad. El ensayo del archivo completo queda a cargo del docente antes de impartir.')]
for i,(title,body,check,note) in enumerate(labs,1):add(title,f'<p class="lab-ribbon">PASO {i} · {[15,10,10,15,10,10,10][i-1]} MIN</p>'+body+proof(check)+lablink(i),note,'lab-taller','Laboratorio · 80–160 min',COST if i==6 else SAMPLE)
add('La tarea comienza cuando llega otro archivo.',flow([('Nueva entrega','Fuente oficial y fecha'),('Contrato','Mapear campos'),('Actualización','Reconciliar y comparar')]),'160–165 min. Descargar un corte oficial QQP acotado. No reemplazar all_data ni mezclar todo el histórico antes de revisar esquema. Es una tarea posterior, no descarga masiva en la última parte de clase. La página oficial y checklist están en tarea.html.','path','Actualización · 160–180 min')
add('Un nombre de columna nuevo exige una decisión explícita.',table(['Entrada nueva','Contrato del taller'],[['fecha_registro, si existe','fechaRegistro; formato documentado'],['cadena_comercial, si existe','cadenaComercial'],['Campo ausente','No inventar; justificar adaptación']]),'165–170 min. Ejemplos de mapeo condicionales, no esquema ya verificado de2026. Abrir cabecera real del nuevo archivo y registrar tipo, unidad, codificación y fecha. No fabricar marca o presentación para que el flujo pase. Si no es compatible, detener ese lote y documentar.','mapping','Actualización · 160–180 min')
add('Reprocesar el mismo lote no debe duplicar Silver.','<div class="two"><div class="stack"><p class="caption">MISMO LOTE</p><h2>Se detiene la ingesta.</h2></div><div class="stack"><p class="caption">MISMAS FILAS, OTRO LOTE</p><h2>Bronze registra; Silver deduplica.</h2></div></div>','170–175 min. Ruta inicial: reconstrucción completaSilver/Gold; simple y comprobable, pero vuelve a leerBronze. La optimización futura es procesar lotes nuevos y recalcular particiones afectadas, con revisiones y llegadas tardías. Nunca llamar incremental a nuestro03. La tarea exige prueba de repetición y conflictos.','idempotence','Actualización · 160–180 min')
add('Entrega una actualización que otra persona pueda auditar.','<div class="check-grid"><div class="check-item"><b>Fuente</b><span>Archivo, corte y manifiesto.</span></div><div class="check-item"><b>Contrato</b><span>Mapa de columnas y reglas.</span></div><div class="check-item"><b>Resultado</b><span>Conteos, cambios y conflictos.</span></div><div class="check-item"><b>Costo</b><span>Jobs, bytes y propuesta.</span></div></div><a class="lab-link" href="tarea.html">Abrir tarea y criterios ↗</a>','175–180 min. Cada equipo justifica arquitectura, forma de actualización y una decisión que sí permite la fuente. Pedir una limitación por escrito. Entregar original,SQL y evidencia; no solo captura del precio menor.','deliverable','Actualización · 160–180 min')
